import {
    ChangeDetectionStrategy,
    Component,
    computed,
    input,
} from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';

@Component({
    selector: 'app-channel-list-loading-state',
    templateUrl: './channel-list-loading-state.component.html',
    styleUrl: './channel-list-loading-state.component.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [TranslatePipe],
})
export class ChannelListLoadingStateComponent {
    readonly view = input<string>('all');

    readonly isGroupsView = computed(() => this.view() === 'groups');
    readonly channelRows = Array.from({ length: 9 }, (_, index) => index);
    readonly groupRows = Array.from({ length: 10 }, (_, index) => index);
    readonly channelMetaWidths = [38, 34, 42, 36, 44, 35, 40, 32, 39];
    readonly channelTitleWidths = [72, 61, 68, 54, 78, 64, 70, 57, 75];
    readonly groupLabelWidths = [78, 66, 84, 58, 73, 69, 81, 62, 76, 71];
}

@if (channelsLoading()) {
    <app-channel-list-loading-state [view]="activeView()" />
} @else if (displayedChannels().length) {
    @if (viewTitle() && activeView() !== 'groups') {
        <header class="context-header">
            <div class="context-header__top">
                <h2>{{ viewTitle() | translate }}</h2>
                @if (
                    activeView() === 'recent' &&
                    recentChannelItems().length > 0
                ) {
                    <button mat-button (click)="clearRecentChannels()">
                        {{ 'WORKSPACE.SHELL.CLEAR_RECENTLY_VIEWED_SECTION' | translate }}
                    </button>
                }
            </div>
        </header>
        <div class="context-divider"></div>
    }

    @switch (activeView()) {
        @case ('all') {
            <app-all-channels-view
                [channels]="displayedChannels()"
                [searchTerm]="workspaceSearchTerm()"
                [channelEpgMap]="channelEpgMap()"
                [channelIconMap]="channelIconMap()"
                [progressTick]="progressTick()"
                [shouldShowEpg]="shouldShowEpg()"
                [itemSize]="itemSize()"
                [activeChannelUrl]="activeChannelUrl()"
                [favoriteIds]="favoriteIds()"
                (channelSelected)="onChannelSelected($event)"
                (favoriteToggled)="onFavoriteToggled($event)"
            />
        }
        @case ('groups') {
            <app-groups-view
                [groupedChannels]="groupedChannels()"
                [searchTerm]="workspaceSearchTerm()"
                [channelEpgMap]="channelEpgMap()"
                [channelIconMap]="channelIconMap()"
                [progressTick]="progressTick()"
                [shouldShowEpg]="shouldShowEpg()"
                [activeChannelUrl]="activeChannelUrl()"
                [favoriteIds]="favoriteIds()"
                [hiddenGroupTitles]="hiddenGroupTitles()"
                [sidebarWidth]="sidebarWidth()"
                (channelSelected)="onChannelSelected($event)"
                (favoriteToggled)="onFavoriteToggled($event)"
                (hiddenGroupTitlesChanged)="
                    onHiddenGroupTitlesChanged($event)
                "
                (sidebarWidthRequested)="onSidebarWidthRequested($event)"
                (sidebarWidthRequestEnded)="onSidebarWidthRequestEnded($event)"
            />
        }
        @case ('favorites') {
            @let favorites = favorites$ | async;
            @if (favorites) {
                <app-favorites-view
                    [favorites]="favorites"
                    [searchTerm]="workspaceSearchTerm()"
                    [channelEpgMap]="channelEpgMap()"
                    [channelIconMap]="channelIconMap()"
                    [progressTick]="progressTick()"
                    [shouldShowEpg]="shouldShowEpg()"
                    [activeChannelUrl]="activeChannelUrl()"
                    (channelSelected)="onChannelSelected($event)"
                    (favoriteToggled)="onFavoriteToggled($event)"
                    (favoritesReordered)="onFavoritesReordered($event)"
                />
            }
        }
        @case ('recent') {
            <app-recent-view
                [recentItems]="recentChannelItems()"
                [searchTerm]="workspaceSearchTerm()"
                [channelEpgMap]="channelEpgMap()"
                [channelIconMap]="channelIconMap()"
                [progressTick]="progressTick()"
                [shouldShowEpg]="shouldShowEpg()"
                [activeChannelUrl]="activeChannelUrl()"
                (channelSelected)="onChannelSelected($event)"
                (removeRecent)="removeRecentChannel($event)"
            />
        }
    }
} @else {
    <div class="empty-source-state">
        <div class="empty-source-state__icon-wrapper">
            <mat-icon class="empty-source-state__icon">folder_off</mat-icon>
        </div>
        <h3 class="empty-source-state__title">
            {{ 'CHANNELS.NO_CHANNELS_FOUND' | translate }}
        </h3>
    </div>
}

