1	import {
2	    CdkVirtualScrollViewport,
3	    ScrollingModule,
4	} from '@angular/cdk/scrolling';
5	import {
6	    AfterViewInit,
7	    ChangeDetectionStrategy,
8	    ChangeDetectorRef,
9	    Component,
10	    computed,
11	    effect,
12	    inject,
13	    input,
14	    OnDestroy,
15	    output,
16	    viewChild,
17	} from '@angular/core';
18	import { MatIcon } from '@angular/material/icon';
19	import { ActivatedRoute } from '@angular/router';
20	import { TranslatePipe } from '@ngx-translate/core';
21	import { Subscription } from 'rxjs';
22	import { debounceTime } from 'rxjs/operators';
23	import {
24	    EpgItem,
25	    EpgProgram,
26	    XtreamCategory,
27	    XtreamItem,
28	} from 'shared-interfaces';
29	import { ChannelListItemComponent } from 'components';
30	import {
31	    PortalChannelSortMode,
32	    sortPortalChannelItems,
33	} from '@iptvnator/portal/shared/util';
34	import { EpgQueueService } from '@iptvnator/portal/xtream/data-access';
35	import { XtreamCredentials } from '@iptvnator/portal/xtream/data-access';
36	import { FavoritesService } from '@iptvnator/portal/xtream/data-access';
37	import { XtreamStore } from '@iptvnator/portal/xtream/data-access';
38	
39	export interface XtreamChannelListItem {
40	    readonly category_id?: string | number;
41	    readonly id?: string | number;
42	    readonly name?: string;
43	    readonly poster_url?: string;
44	    readonly stream_icon?: string;
45	    readonly title?: string;
46	    readonly type?: 'live' | 'movie' | 'series' | 'vod';
47	    readonly xtream_id: number;
48	}
49	
50	interface XtreamCategoryLike {
51	    readonly category_id?: string | number;
52	    readonly id?: string | number;
53	}
54	
55	@Component({
56	    selector: 'app-portal-channels-list',
57	    templateUrl: './portal-channels-list.component.html',
58	    styleUrls: ['./portal-channels-list.component.scss'],
59	    changeDetection: ChangeDetectionStrategy.OnPush,
60	    imports: [
61	        ChannelListItemComponent,
62	        MatIcon,
63	        ScrollingModule,
64	        TranslatePipe,
65	    ],
66	})
67	export class PortalChannelsListComponent implements AfterViewInit, OnDestroy {
68	    readonly playClicked = output<XtreamChannelListItem>();
69	    readonly sortMode = input<PortalChannelSortMode>('server');
70	    readonly channelsOverride = input<XtreamChannelListItem[] | null>(null);
71	    readonly searchTermInput = input('');
72	
73	    readonly xtreamStore = inject(XtreamStore);
74	    private readonly favoritesService = inject(FavoritesService);
75	    private readonly epgQueueService = inject(EpgQueueService);
76	    private readonly route = inject(ActivatedRoute);
77	    readonly isSelectedTypeContentLoading =
78	        this.xtreamStore.selectedTypeContentLoading;
79	    readonly loadingRows = Array.from({ length: 9 }, (_, index) => index);
80	    readonly channels = computed(() => {
81	        const override = this.channelsOverride();
82	        if (Array.isArray(override)) {
83	            return override;
84	        }
85	
86	        return this.xtreamStore.selectItemsFromSelectedCategory() as XtreamChannelListItem[];
87	    });
88	    readonly sortedChannels = computed(() => {
89	        const mode = this.sortMode();
90	        const channels = this.channels();
91	        return sortPortalChannelItems(
92	            channels,
93	            mode,
94	            (item) => item.title ?? item.name
95	        );
96	    });
97	    readonly filteredChannels = computed(() => {
98	        const term = this.searchTermInput().trim().toLowerCase();
99	        const channels = this.sortedChannels();
100	
101	        if (!term) {
102	            return channels;
103	        }
104	
105	        return channels.filter((item) =>
106	            `${item.title ?? ''} ${item.name ?? ''}`
107	                .toLowerCase()
108	                .includes(term)
109	        );
110	    });
111	
112	    favorites = new Map<string, boolean>();
113	    epgPrograms = new Map<number, EpgProgram>();
114	    currentProgramsProgress = new Map<number, number>();
115	
116	    readonly viewport = viewChild(CdkVirtualScrollViewport);
117	
118	    private subscriptions = new Subscription();
119	
120	    constructor(private cdr: ChangeDetectorRef) {
121	        effect(() => {
122	            const selectedItem = this.xtreamStore.selectedItem();
123	            const epgItems = this.xtreamStore.epgItems();
124	
125	            if (!selectedItem?.xtream_id || epgItems.length === 0) {
126	                return;
127	            }
128	
129	            const previewProgram = this.pickPreviewProgram(epgItems);
130	            if (!previewProgram) {
131	                return;
132	            }
133	
134	            this.applyProgram(selectedItem.xtream_id, previewProgram);
135	        });
136	    }
137	
138	    trackBy(_index: number, item: XtreamChannelListItem | XtreamItem) {
139	        return item.xtream_id;
140	    }
141	
142	    ngOnInit(): void {
143	        const { categoryId } = this.route.snapshot.params;
144	        if (categoryId && !this.channelsOverride())
145	            this.xtreamStore.setSelectedCategory(Number(categoryId));
146	
147	        const playlist = this.xtreamStore.currentPlaylist();
148	        if (playlist) {
149	            this.favoritesService
150	                .getFavorites(playlist.id)
151	                .subscribe((favorites) => {
152	                    favorites.forEach((fav) => {
153	                        this.favorites.set(
154	                            this.getFavoriteKey(fav.xtream_id, fav.type),
155	                            true
156	                        );
157	                    });
158	                });
159	        }
160	
161	        // Subscribe to EPG results from the queue service
162	        this.subscriptions.add(
163	            this.epgQueueService.epgResult$.subscribe(({ streamId, items }) => {
164	                const previewProgram = this.pickPreviewProgram(items);
165	                if (previewProgram) {
166	                    this.applyProgram(streamId, previewProgram);
167	                }
168	            })
169	        );
170	    }
171	
172	    ngAfterViewInit() {
173	        const vp = this.viewport();
174	        if (vp && this.xtreamStore.selectedContentType() === 'live') {
175	            this.subscriptions.add(
176	                vp.renderedRangeStream
177	                    .pipe(debounceTime(300))
