    &:focus-within {
        border-color: var(--app-selection-border);
        box-shadow: 0 0 0 3px color-mix(in srgb, var(--app-selection-color) 16%, transparent);
    }

    mat-icon {
        width: 18px;
        height: 18px;
        font-size: 18px;
        opacity: 0.68;
        flex-shrink: 0;
    }

    input {
        flex: 1;
        border: none;
        outline: none;
        background: transparent;
        color: inherit;
        font: inherit;
        font-size: 0.875rem;

        &:disabled {
            cursor: not-allowed;
            opacity: 0.5;
        }

        &::placeholder {
            opacity: 0.62;
        }
    }
}

