411	                return;
412	            }
413	
414	            this.fallbackEpgPrograms.set(
415	                fallbackItems.map((epgItem) =>
416	                    this.toProgram(epgItem, normalizedChannelId)
417	                )
418	            );
419	        } catch (error) {
420	            this.logger.warn('Failed to load Stalker live EPG', error);
421	            if (this.isCurrentEpgRequest(requestId, normalizedChannelId)) {
422	                this.fallbackEpgPrograms.set([]);
423	            }
424	        } finally {
425	            if (this.isCurrentEpgRequest(requestId, normalizedChannelId)) {
426	                this.isLoadingFallbackEpg.set(false);
427	            }
428	        }
429	    }
430	
431	    private clearEpgPreviewMaps() {
432	        this.epgPreviewPrograms.clear();
433	        this.currentProgramsProgress.clear();
434	    }
435	
436	    private syncBulkEpgPreviews(channels: StalkerItvChannel[]): void {
437	        this.clearEpgPreviewMaps();
438	
439	        const bulkProgramsByChannel = this.stalkerStore.bulkItvEpgByChannel();
440	        if (
441	            channels.length === 0 ||
442	            Object.keys(bulkProgramsByChannel).length === 0
443	        ) {
444	            this.cdr.markForCheck();
445	            return;
446	        }
447	
448	        for (const channel of channels) {
449	            const channelId = normalizeStalkerEntityId(channel.id);
450	            const currentProgram = this.findCurrentProgram(
451	                bulkProgramsByChannel[channelId] ?? []
452	            );
453	
454	            if (!currentProgram) {
455	                continue;
456	            }
457	
458	            this.epgPreviewPrograms.set(channelId, currentProgram);
459	            this.updateProgramProgress(channelId, currentProgram);
460	        }
461	
462	        this.cdr.markForCheck();
463	    }
464	
465	    private updateProgramProgress(
466	        channelId: string | number,
467	        program: EpgProgram
468	    ): void {
469	        const startMs = this.getProgramTimestampMs(
470	            program.start,
471	            program.startTimestamp
472	        );
473	        const stopMs = this.getProgramTimestampMs(
474	            program.stop,
475	            program.stopTimestamp
476	        );
477	        const nowMs = Date.now();
478	
479	        if (
480	            Number.isFinite(startMs) &&
481	            Number.isFinite(stopMs) &&
482	            nowMs >= startMs &&
483	            nowMs <= stopMs &&
484	            stopMs > startMs
485	        ) {
486	            this.currentProgramsProgress.set(
487	                channelId,
488	                ((nowMs - startMs) / (stopMs - startMs)) * 100
489	            );
490	            return;
491	        }
492	
493	        this.currentProgramsProgress.delete(channelId);
494	    }
