497	        this.removeScrollListener();
498	
499	        const container = this.scrollContainer()?.nativeElement;
500	        if (!container) return;
501	
502	        const onScroll = () => {
503	            if (this.isLoadingMore() || !this.hasMoreItems()) return;
504	
505	            const { scrollTop, scrollHeight, clientHeight } = container;
506	            const scrollThreshold = 150;
507	
508	            if (scrollHeight - scrollTop - clientHeight <= scrollThreshold) {
509	                this.loadMore();
510	            }
511	        };
512	
513	        container.addEventListener('scroll', onScroll, { passive: true });
514	        this.scrollListener = () =>
515	            container.removeEventListener('scroll', onScroll);
516	    }
517	
518	    private checkIfNeedsMoreContent() {
519	        const container = this.scrollContainer()?.nativeElement;
520	        if (!container) return;
521	        if (this.isLoadingMore() || !this.hasMoreItems()) return;
522	
523	        const { scrollHeight, clientHeight } = container;
524	        if (scrollHeight <= clientHeight) {
525	            this.loadMore();
526	        }
527	    }
528	
529	    private removeScrollListener() {
530	        if (this.scrollListener) {
531	            this.scrollListener();
532	            this.scrollListener = null;
533	        }
534	    }
535	
