537	        return {
538	            start: item.start,
539	            stop: item.stop || item.end,
540	            channel: String(channelId),
541	            title: item.title,
542	            desc: item.description || null,
543	            category: null,
544	            startTimestamp: this.toTimestamp(item.start_timestamp, item.start),
545	            stopTimestamp: this.toTimestamp(
546	                item.stop_timestamp,
547	                item.stop || item.end
548	            ),
549	        };
550	    }
