566	    private toTimestamp(
567	        rawTimestamp: string | number | null | undefined,
568	        rawDate: string
569	    ): number | null {
570	        const timestamp = Number.parseInt(String(rawTimestamp ?? ''), 10);
571	        if (Number.isFinite(timestamp) && timestamp > 0) {
572	            return timestamp;
573	        }
574	
575	        const parsedDate = Date.parse(rawDate);
576	        return Number.isFinite(parsedDate)
577	            ? Math.floor(parsedDate / 1000)
578	            : null;
579	    }
