584	            programs.find((program) => {
585	                const start = this.getProgramTimestampMs(
586	                    program.start,
587	                    program.startTimestamp
588	                );
589	                const stop = this.getProgramTimestampMs(
590	                    program.stop,
591	                    program.stopTimestamp
592	                );
593	                return (
594	                    start !== null &&
595	                    stop !== null &&
596	                    now >= start &&
597	                    now < stop
598	                );
599	            }) ?? null
600	        );
601	    }
602	
603	    private getProgramTimestampMs(
604	        rawDate: string,
605	        rawTimestamp?: number | null
606	    ): number | null {
607	        if (Number.isFinite(rawTimestamp) && Number(rawTimestamp) > 0) {
608	            return Number(rawTimestamp) * 1000;
609	        }
610	
611	        const parsedDate = Date.parse(rawDate);
612	        return Number.isFinite(parsedDate) ? parsedDate : null;
