293	            return 'recent';
294	        }
295	
296	        if (!this.playlistsLoaded()) {
297	            return null;
298	        }
299	
300	        return this.playlists()
301	            .map((playlist) =>
302	                [
303	                    playlist._id,
304	                    playlist.serverUrl
305	                        ? 'xtream'
306	                        : playlist.macAddress
307	                          ? 'stalker'
308	                          : 'm3u',
309	                    JSON.stringify(playlist.favorites ?? []),
310	                ].join('::')
311	            )
312	            .join('|');
313	    });
314	    private readonly loadRequest = computed(() => ({
315	        mode: this.mode(),
316	        portalType: this.portalType(),
317	        playlistId: this.playlistId(),
318	        scope: this.effectiveScope(),
319	        reloadKey: this.favoritesReloadKey(),
320	    }));
321	
322	    private loadRequestId = 0;
323	
324	    private readonly loadEffect = effect(() => {
325	        const { mode, portalType, playlistId, scope } = this.loadRequest();
326	        untracked(() => {
327	            void this.loadData({
328	                mode,
329	                portalType,
330	                playlistId,
331	                scope,
332	            });
333	        });
334	    });
335	    private readonly persistCollectionViewState = effect(() => {
336	        const selectedContentType = this.selectedContentType();
337	        const scope = this.showScopeToggle() ? this.scope() : undefined;
338	
339	        untracked(() => {
340	            this.syncCollectionViewStateToHistory({
341	                selectedContentType,
342	                scope,
343	            });
344	        });
345	    });
346	    private readonly crossProviderDetailRedirect = effect(() => {
347	        const item = this.selectedDetailItem();
348	        if (!item || this.canRenderInlineDetailOnCurrentRoute(item)) {
349	            return;
350	        }
351	
352	        const navigation = this.getGlobalCollectionDetailNavigation(item);
353	        if (!navigation) {
354	            return;
355	        }
356	
357	        untracked(() => {
358	            this.selectedDetailItem.set(null);
359	            void this.router.navigate(navigation.link, {
360	                state: navigation.state,
361	            });
362	        });
363	    });
364	    private readonly workspaceCommandEffect = effect((onCleanup) => {
365	        if (!this.isWorkspaceLayout) {
366	            return;
367	        }
368	
369	        const items = this.currentTypeItems();
370	        if (items.length === 0) {
371	            return;
372	        }
373	
374	        const unregister = this.workspaceViewCommands.registerCommand({
375	            id: `unified-collection-clear-current-${this.mode()}`,
376	            group: 'view',
377	            icon: 'delete_sweep',
378	            labelKey: this.clearButtonTooltipKey(),
379	            labelParams: () => ({
380	                type: this.translate.instant(this.currentTypeLabelKey()),
381	            }),
382	            descriptionKey:
383	                'WORKSPACE.SHELL.COMMANDS.CLEAR_CURRENT_VIEW_DESCRIPTION',
384	            descriptionParams: () => ({
385	                type: this.translate.instant(this.currentTypeLabelKey()),
386	            }),
387	            keywords: () =>
388	                this.mode() === 'favorites'
389	                    ? ['clear', 'favorites', 'remove', this.selectedContentType()]
390	                    : ['clear', 'recent', 'history', this.selectedContentType()],
391	            priority: 10,
392	            run: () => this.clearAllCurrent(),
393	        });
394	
395	        onCleanup(unregister);
396	    });
397	
398	    constructor() {
399	        if (typeof window !== 'undefined') {
400	            const onPopState = () => {
401	                this.syncCollectionViewStateFromHistory();
402	                this.syncDetailFromHistoryState();
403	            };
404	            window.addEventListener('popstate', onPopState);
405	            this.destroyRef.onDestroy(() => {
406	                window.removeEventListener('popstate', onPopState);
407	            });
408	        }
409	    }
410	
411	    ngAfterContentInit(): void {
412	        this.syncCollectionViewStateFromHistory();
413	        this.syncDetailFromHistoryState();
414	    }
415	
416	    onScopeChange(value: CollectionScope): void {
417	        if (!this.showScopeToggle()) {
418	            return;
419	        }
420	
421	        this.scope.set(value);
422	        this.scopeService.setScope(this.scopeKey(), value);
423	    }
424	
425	    onContentTypeChange(value: CollectionContentType): void {
426	        this.selectedContentType.set(value);
427	    }
428	
429	    readonly emptyStateIcon = computed(() =>
430	        this.mode() === 'favorites' ? 'favorite_border' : 'history_toggle_off'
431	    );
432	
433	    readonly emptyStateTitleKey = computed(() =>
434	        this.mode() === 'favorites'
435	            ? 'WORKSPACE.GLOBAL_FAVORITES.NO_ITEMS_TITLE'
436	            : 'WORKSPACE.GLOBAL_RECENT.NO_ITEMS_TITLE'
437	    );
438	
439	    readonly emptyStateBodyKey = computed(() =>
440	        this.mode() === 'favorites'
441	            ? 'WORKSPACE.GLOBAL_FAVORITES.NO_ITEMS_BODY'
442	            : 'WORKSPACE.GLOBAL_RECENT.NO_ITEMS_BODY'
443	    );
444	
445	    goToDashboard(): void {
446	        void this.router.navigate(['/workspace', 'dashboard']);
447	    }
448	
449	    setFavSortMode(mode: FavoritesChannelSortMode): void {
450	        this.favSortMode.set(mode);
451	        persistFavoritesChannelSortMode(mode);
452	    }
453	
454	    onGridItemSelected(item: UnifiedCollectionItem): void {
455	        this.syncCurrentCollectionViewState();
456	
457	        if (this.canOpenInlineDetail(item)) {
458	            this.pushInlineDetailState(item);
459	            this.openInlineDetail(item);
460	            return;
461	        }
462	
463	        const globalDetailNavigation =
464	            this.getGlobalCollectionDetailNavigation(item);
465	        if (globalDetailNavigation) {
466	            void this.router.navigate(globalDetailNavigation.link, {
467	                state: globalDetailNavigation.state,
468	            });
469	            return;
470	        }
471	
472	        const navigation = getUnifiedCollectionNavigation(item);
473	        if (!navigation) {
474	            return;
475	        }
476	
477	        const state =
478	            item.sourceType === 'stalker' && item.contentType !== 'live'
479	                ? {
480	                      ...(navigation.state ?? {}),
481	                      [STALKER_RETURN_TO_STATE_KEY]: this.router.url,
482	                  }
483	                : navigation.state;
484	
485	        void this.router.navigate(navigation.link, { state });
486	    }
487	
488	    async onRemoveItem(item: UnifiedCollectionItem): Promise<void> {
489	        if (this.mode() === 'favorites') {
490	            await this.favoritesData.removeFavorite(item);
491	            this.favoriteUidSet.update((favoriteUids) => {
492	                const nextFavoriteUids = new Set(favoriteUids);
493	                nextFavoriteUids.delete(item.uid);
494	                return nextFavoriteUids;
495	            });
496	        } else {
497	            await this.recentData.removeRecentItem(item);
498	        }
499	        this.allItems.update((items) =>
500	            items.filter((i) => i.uid !== item.uid)
501	        );
502	    }
503	
504	    async onFavoriteToggled(item: UnifiedCollectionItem): Promise<void> {
505	        if (this.mode() !== 'recent') {
506	            return;
507	        }
508	
509	        const nextFavoriteUids = new Set(this.favoriteUidSet());
510	
511	        if (nextFavoriteUids.has(item.uid)) {
512	            await this.favoritesData.removeFavorite(item);
513	            nextFavoriteUids.delete(item.uid);
514	        } else {
515	            await this.favoritesData.addFavorite(item);
516	            nextFavoriteUids.add(item.uid);
517	        }
518	
519	        this.favoriteUidSet.set(nextFavoriteUids);
520	    }
521	
522	    clearAllCurrent(): void {
523	        const itemsToRemove = this.currentTypeItems();
524	        if (itemsToRemove.length === 0) {
525	            return;
526	        }
527	
528	        const isFavorites = this.mode() === 'favorites';
529	        const type = this.translate.instant(this.currentTypeLabelKey());
530	        const isPlaylistScope = this.effectiveScope() === 'playlist';
531	        const titleKey = isFavorites
532	            ? 'WORKSPACE.SHELL.CLEAR_FAVORITES_DIALOG_TITLE'
533	            : 'WORKSPACE.SHELL.CLEAR_RECENTLY_VIEWED_DIALOG_TITLE';
534	        const messageKey = isFavorites
535	            ? isPlaylistScope
536	                ? 'WORKSPACE.SHELL.CLEAR_FAVORITES_DIALOG_MESSAGE_PLAYLIST'
537	                : 'WORKSPACE.SHELL.CLEAR_FAVORITES_DIALOG_MESSAGE_ALL'
538	            : isPlaylistScope
539	              ? 'WORKSPACE.SHELL.CLEAR_RECENTLY_VIEWED_DIALOG_MESSAGE_PLAYLIST'
540	              : 'WORKSPACE.SHELL.CLEAR_RECENTLY_VIEWED_DIALOG_MESSAGE_ALL';
541	
542	        this.dialogService.openConfirmDialog({
543	            title: this.translate.instant(titleKey, { type }),
544	            message: this.translate.instant(messageKey, { type }),
545	            onConfirm: async () => {
546	                if (isFavorites) {
547	                    await this.clearCurrentFavorites(itemsToRemove);
548	                    return;
549	                }
550	
551	                const removedType = this.selectedContentType();
552	                this.allItems.update((items) =>
553	                    items.filter((item) => item.contentType !== removedType)
554	                );
555	                const remaining = this.availableTypes();
556	                if (remaining.length > 0) {
557	                    this.selectedContentType.set(remaining[0]);
558	                }
559	                void this.recentData.removeRecentItemsBatch(itemsToRemove);
560	            },
561	        });
562	    }
563	
564	    async onReorder(items: UnifiedCollectionItem[]): Promise<void> {
565	        const nonLive = this.allItems().filter((i) => i.contentType !== 'live');
566	        this.allItems.set([...items, ...nonLive]);
567	        await this.favoritesData.reorder(items, {
568	            scope: this.effectiveScope(),
569	            playlistId: this.playlistId(),
570	            portalType: this.portalType(),
571	        });
572	    }
573	
574	    onItemPlayed(item: UnifiedCollectionItem): void {
575	        if (this.mode() !== 'recent') {
576	            return;
577	        }
578	
579	        this.allItems.update((items) => {
580	            const nextItems = [
581	                item,
582	                ...items.filter((candidate) => candidate.uid !== item.uid),
583	            ];
584	            return nextItems.sort(
585	                (a, b) =>
586	                    new Date(b.viewedAt ?? 0).getTime() -
587	                    new Date(a.viewedAt ?? 0).getTime()
588	            );
589	        });
590	    }
591	
592	    private async clearCurrentFavorites(
593	        itemsToRemove: UnifiedCollectionItem[]
594	    ): Promise<void> {
595	        const removedType = this.selectedContentType();
596	        this.allItems.update((items) =>
597	            items.filter((item) => item.contentType !== removedType)
598	        );
599	        const remaining = this.availableTypes();
600	        if (remaining.length > 0) {
601	            this.selectedContentType.set(remaining[0]);
602	        }
603	
604	        try {
605	            await this.favoritesData.clearFavorites(itemsToRemove);
606	        } catch {
607	            await this.reloadCurrentCollection();
608	        }
609	    }
610	
611	    private async loadData(params: {
612	        mode: 'favorites' | 'recent';
613	        portalType?: string;
614	        playlistId?: string;
615	        scope: CollectionScope;
616	    }): Promise<void> {
617	        const requestId = ++this.loadRequestId;
618	        if (this.allItems().length === 0) {
619	            this.isLoading.set(true);
620	        }
621	
622	        try {
623	            const items =
624	                params.mode === 'favorites'
625	                    ? await this.favoritesData.getFavorites(
626	                          params.scope,
627	                          params.playlistId,
628	                          params.portalType
629	                      )
630	                    : await this.recentData.getRecentItems(
631	                          params.scope,
632	                          params.playlistId,
633	                          params.portalType
634	                      );
635	            const favoriteUids =
636	                params.mode === 'favorites'
637	                    ? new Set(items.map((item) => item.uid))
638	                    : await this.loadFavoriteUidSet(params);
639	            if (requestId !== this.loadRequestId) {
640	                return;
641	            }
642	            this.allItems.set(items);
643	            this.favoriteUidSet.set(favoriteUids);
644	            this.autoSelectContentType();
645	            if (
646	                this.pendingAutoOpenLiveItem() &&
647	                items.some((item) => item.contentType === 'live')
648	            ) {
649	                this.selectedContentType.set('live');
650	            }
651	        } catch {
652	            if (requestId !== this.loadRequestId) {
653	                return;
654	            }
655	            this.allItems.set([]);
656	        } finally {
657	            if (requestId === this.loadRequestId) {
658	                this.isLoading.set(false);
659	            }
660	        }
661	    }
662	
663	    private async reloadCurrentCollection(): Promise<void> {
664	        await this.loadData({
665	            mode: this.mode(),
666	            portalType: this.portalType(),
667	            playlistId: this.playlistId(),
668	            scope: this.effectiveScope(),
669	        });
670	    }
671	
672	    private async loadFavoriteUidSet(params: {
673	        portalType?: string;
674	        playlistId?: string;
675	        scope: CollectionScope;
676	    }): Promise<ReadonlySet<string>> {
677	        try {
678	            const favorites = await this.favoritesData.getFavorites(
679	                params.scope,
680	                params.playlistId,
681	                params.portalType
682	            );
683	            return new Set(favorites.map((item) => item.uid));
684	        } catch {
685	            return new Set<string>();
686	        }
687	    }
688	
689	    private autoSelectContentType(): void {
690	        if (this.selectedDetailItem()) {
691	            return;
692	        }
693	
694	        const types = this.availableTypes();
695	        if (types.length > 0 && !types.includes(this.selectedContentType())) {
696	            this.selectedContentType.set(types[0]);
697	        }
698	    }
699	
700	    onLiveAutoOpenHandled(): void {
701	        this.pendingAutoOpenLiveItem.set(null);
702	        clearNavigationStateKeys([OPEN_LIVE_COLLECTION_ITEM_STATE_KEY]);
703	    }
704	
705	    private readonly requestCloseDetail = (): void => {
706	        if (getOpenCollectionDetailItemState(window.history.state)) {
707	            window.history.back();
708	            return;
709	        }
710	
711	        this.clearInlineDetail();
712	    };
713	
714	    private canOpenInlineDetail(item: UnifiedCollectionItem): boolean {
715	        return (
716	            Boolean(this.detailTemplate()) &&
717	            item.contentType !== 'live' &&
718	            (item.sourceType === 'xtream' || item.sourceType === 'stalker') &&
719	            this.canRenderInlineDetailOnCurrentRoute(item)
720	        );
721	    }
722	
723	    private canRenderInlineDetailOnCurrentRoute(
724	        item: UnifiedCollectionItem
725	    ): boolean {
726	        const url = this.router.url;
727	
728	        if (url.includes('/workspace/xtreams/')) {
729	            return item.sourceType === 'xtream';
730	        }
731	
732	        if (url.includes('/workspace/stalker/')) {
733	            return item.sourceType === 'stalker';
734	        }
735	
736	        if (
737	            url.includes('/workspace/global-favorites') ||
738	            url.includes('/workspace/global-recent')
739	        ) {
740	            return (
741	                item.sourceType === 'xtream' || item.sourceType === 'stalker'
742	            );
743	        }
744	
745	        const portalType = this.portalType();
746	        return !portalType || portalType === item.sourceType;
747	    }
748	
749	    private getGlobalCollectionDetailNavigation(item: UnifiedCollectionItem) {
750	        if (
751	            item.contentType === 'live' ||
752	            (item.sourceType !== 'xtream' && item.sourceType !== 'stalker')
753	        ) {
754	            return null;
755	        }
756	
757	        return buildGlobalCollectionDetailNavigationTarget(this.mode(), item);
758	    }
759	
760	    private openInlineDetail(item: UnifiedCollectionItem): void {
761	        this.selectedContentType.set(item.contentType);
762	        this.selectedDetailItem.set(item);
763	    }
764	
765	    private clearInlineDetail(): void {
766	        this.selectedDetailItem.set(null);
767	        this.autoSelectContentType();
768	        clearNavigationStateKeys([OPEN_COLLECTION_DETAIL_STATE_KEY]);
769	    }
770	
771	    private pushInlineDetailState(item: UnifiedCollectionItem): void {
772	        const currentState = window.history.state ?? {};
773	        window.history.pushState(
774	            {
775	                ...currentState,
776	                [OPEN_COLLECTION_DETAIL_STATE_KEY]:
777	                    buildOpenCollectionDetailItemState(item),
778	            },
779	            document.title
780	        );
781	    }
782	
783	    private syncCollectionViewStateFromHistory(): void {
784	        const collectionViewState = getCollectionViewState(
785	            window.history.state
786	        );
787	        this.historyCollectionViewState.set(collectionViewState);
788	
789	        if (collectionViewState?.selectedContentType) {
790	            this.selectedContentType.set(
791	                collectionViewState.selectedContentType
792	            );
793	        }
794	    }
795	
796	    private syncCurrentCollectionViewState(): void {
797	        this.syncCollectionViewStateToHistory({
798	            selectedContentType: this.selectedContentType(),
799	            scope: this.showScopeToggle() ? this.scope() : undefined,
800	        });
801	    }
802	
803	    private syncCollectionViewStateToHistory(state: CollectionViewState): void {
804	        const nextCollectionViewState = buildCollectionViewState(state);
805	        const currentCollectionViewState = this.historyCollectionViewState();
806	
807	        if (
808	            this.isSameCollectionViewState(
809	                currentCollectionViewState,
810	                nextCollectionViewState
811	            )
812	        ) {
813	            return;
814	        }
815	
816	        const currentState = this.toHistoryStateRecord(window.history.state);
817	        const nextState = { ...currentState };
818	
819	        if (nextCollectionViewState) {
820	            nextState[COLLECTION_VIEW_STATE_KEY] = nextCollectionViewState;
821	        } else {
822	            delete nextState[COLLECTION_VIEW_STATE_KEY];
823	        }
824	
825	        window.history.replaceState(nextState, document.title);
826	        this.historyCollectionViewState.set(nextCollectionViewState);
827	    }
828	
829	    private syncDetailFromHistoryState(): void {
830	        const detailItem = getOpenCollectionDetailItemState(
831	            window.history.state
832	        )?.item;
833	
834	        if (detailItem && this.canOpenInlineDetail(detailItem)) {
835	            this.openInlineDetail(detailItem);
836	            return;
837	        }
838	
839	        if (this.selectedDetailItem()) {
840	            this.clearInlineDetail();
841	        }
842	    }
843	
844	    private isSameCollectionViewState(
845	        left: CollectionViewState | null,
846	        right: CollectionViewState | null
847	    ): boolean {
848	        return (
849	            left?.selectedContentType === right?.selectedContentType &&
850	            left?.scope === right?.scope
851	        );
852	    }
853	
854	    private toHistoryStateRecord(state: unknown): Record<string, unknown> {
855	        return state && typeof state === 'object'
856	            ? { ...(state as Record<string, unknown>) }
857	            : {};
858	    }
859	}
